"""Flexible DNS server for transport probing.

Usage: trans_flex.py <PORT> <MODE>
Modes:
  tc_empty        UDP+TCP: respond TC=1, no records
  tc_answer       UDP+TCP: respond TC=1 with an A answer
  normal          respond with A answer
  tc_tcp_too      UDP: TC=1 empty; TCP: TC=1 empty too
  silent_udp      UDP: never respond; TCP: normal
  silent_tcp      UDP: normal; TCP: accept then never respond
  close_tcp       UDP: normal; TCP: accept then close immediately
  close_tcp_mid   TCP: read query, close without responding
  garbage_udp     UDP: respond with random garbage bytes
  garbage_tcp     TCP: respond with garbage
  trunc_pkt       UDP: respond with first 10 bytes of a valid response
  wrong_txid      UDP+TCP: respond with txid+1
  wrong_question  UDP+TCP: respond with different qname in question section
  no_question     UDP+TCP: respond with qdcount=0
  bad_crc_like    UDP: valid response but flip a byte in the answer name
"""
import sys, socket, struct, threading, os
sys.path.insert(0, "/workspace/probe")
from dnskit import *

PORT = int(sys.argv[1])
MODE = sys.argv[2]

def make_response(q, proto):
    if MODE == "garbage_udp" and proto == "udp":
        return os.urandom(40)
    if MODE == "garbage_tcp" and proto == "tcp":
        return os.urandom(40)
    if MODE == "trunc_pkt" and proto == "udp":
        r = Response(q)
        r.add_answer("example.com", "A", 300, A("1.2.3.4"))
        return r.build()[:10]
    r = Response(q)
    if MODE == "wrong_txid":
        r.txid = (r.txid + 1) & 0xFFFF
    if MODE == "wrong_question":
        r._qraw = name("other.com") + struct.pack(">HH", 1, 1)
    if MODE == "no_question":
        r._qraw = b""
        r.qdcount = 0
    if MODE in ("tc_empty",):
        r.flags |= (1 << 9)
        return r.build()
    if MODE == "tc_answer":
        r.flags |= (1 << 9)
    if MODE == "tc_tcp_too":
        r.flags |= (1 << 9)
        return r.build()
    r.add_answer("example.com", "A", 300, A("1.2.3.4"))
    b = bytearray(r.build())
    if MODE == "bad_crc_like" and proto == "udp":
        b[-1] ^= 0xFF
    return bytes(b)

def udp_loop(u):
    while True:
        try:
            data, addr = u.recvfrom(65535)
            print("UDP-QUERY", parse_query(data), flush=True)
            if MODE == "silent_udp":
                continue
            resp = make_response(data, "udp")
            if resp is not None:
                u.sendto(resp, addr)
        except Exception as e:
            print("udp err", e, flush=True)

def tcp_conn(conn):
    try:
        hdr = b""
        while len(hdr) < 2:
            c = conn.recv(2 - len(hdr))
            if not c:
                return
            hdr += c
        (length,) = struct.unpack(">H", hdr)
        data = b""
        while len(data) < length:
            c = conn.recv(length - len(data))
            if not c:
                return
            data += c
        print("TCP-QUERY", parse_query(data), flush=True)
        if MODE in ("silent_tcp",):
            threading.Event().wait()  # never respond
        if MODE in ("close_tcp", "close_tcp_mid"):
            return  # close without responding
        resp = make_response(data, "tcp")
        if resp is not None:
            conn.sendall(struct.pack(">H", len(resp)) + resp)
    except Exception as e:
        print("tcp err", e, flush=True)
    finally:
        conn.close()

def tcp_loop(t):
    while True:
        try:
            conn, _ = t.accept()
            threading.Thread(target=tcp_conn, args=(conn,), daemon=True).start()
        except Exception as e:
            print("accept err", e, flush=True)

u = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
u.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
u.bind(("127.0.0.1", PORT))
t = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
t.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
t.bind(("127.0.0.1", PORT))
t.listen(5)
threading.Thread(target=udp_loop, daemon=True).start()
threading.Thread(target=tcp_loop, daemon=True).start()
print("serving", PORT, MODE, flush=True)
threading.Event().wait()

